mapper.select:
SELECT chunk_id, doc_type, route_action, text, rerank_text, section_path, 1 - (embedding <=> CAST(#{queryVector} AS vector)) AS score, 1 - (embedding <=> CAST(#{queryVector} AS vector)) AS vector_similarity FROM knowledge_vectors
doc_type = #{docType}
ORDER BY embedding <=> CAST(#{queryVector} AS vector) LIMIT #{topK}

SELECT chunk_id, doc_type, route_action, text, rerank_text, section_path, ts_rank_cd(text_tsv, plainto_tsquery('jiebacfg', #{queryText})) AS score FROM knowledge_vectors WHERE text_tsv @@ plainto_tsquery('jiebacfg', #{queryText})
AND doc_type = #{docType}
ORDER BY score DESC LIMIT #{topK}

WITH vector_search AS ( SELECT chunk_id, row_number() OVER (ORDER BY embedding <=> CAST(#{queryVector} AS vector)) AS v_rank FROM knowledge_vectors
doc_type = #{docType}
ORDER BY embedding <=> CAST(#{queryVector} AS vector) LIMIT 50 ), keyword_search AS ( SELECT chunk_id, row_number() OVER (ORDER BY ts_rank_cd(text_tsv, plainto_tsquery('jiebacfg', #{queryText})) DESC) AS k_rank FROM knowledge_vectors WHERE text_tsv @@ plainto_tsquery('jiebacfg', #{queryText})
AND doc_type = #{docType}
ORDER BY ts_rank_cd(text_tsv, plainto_tsquery('jiebacfg', #{queryText})) DESC LIMIT 50 ), fused AS ( SELECT coalesce(v.chunk_id, k.chunk_id) AS chunk_id, v.v_rank AS vector_rank, k.k_rank AS keyword_rank, coalesce(1.0 / (60 + v.v_rank), 0.0) + coalesce(1.0 / (60 + k.k_rank), 0.0) AS rrf_score FROM vector_search v FULL OUTER JOIN keyword_search k ON v.chunk_id = k.chunk_id ) SELECT kv.chunk_id, kv.doc_type, kv.route_action, kv.text, kv.rerank_text, kv.section_path, f.rrf_score AS score, f.vector_rank, f.keyword_rank, f.rrf_score, 1 - (kv.embedding <=> CAST(#{queryVector} AS vector)) AS vector_similarity FROM fused f JOIN knowledge_vectors kv ON kv.chunk_id = f.chunk_id ORDER BY f.rrf_score DESC LIMIT #{topK}

WITH q AS ( SELECT AS query ) SELECT kv.chunk_id, kv.doc_type, kv.route_action, kv.text, kv.rerank_text, kv.section_path, (SELECT coalesce(sum(array_length(u.positions, 1)), 0) FROM unnest(kv.text_tsv) u WHERE btrim(u.lexeme) <> '') AS doc_length FROM knowledge_vectors kv, q WHERE kv.text_tsv @@ q.query
AND kv.doc_type = #{docType}
ORDER BY ts_rank_cd(kv.text_tsv, q.query) DESC, kv.chunk_id LIMIT #{limit}

SELECT kv.chunk_id AS chunk_id, u.lexeme AS lexeme, array_length(u.positions, 1) AS tf
FROM knowledge_vectors kv, unnest(kv.text_tsv) u
WHERE kv.chunk_id IN
#{id}
AND u.lexeme IN
#{t}
